#include <bits/stdc++.h>
using namespace std;

using int64 = long long;
using i128 = __int128_t;

void printInt128(i128 x) {
    if (x == 0) {
        cout << 0;
        return;
    }
    if (x < 0) {
        cout << '-';
        x = -x;
    }
    string s;
    while (x > 0) {
        s.push_back(char('0' + x % 10));
        x /= 10;
    }
    reverse(s.begin(), s.end());
    cout << s;
}

int main() {
    ios::sync_with_stdio(false);
    cin.tie(nullptr);

    int64 c0, hr0, hb0, wr0, wb0;
    cin >> c0 >> hr0 >> hb0 >> wr0 >> wb0;

    i128 c = c0, ha = hr0, hb = hb0, wa = wr0, wb = wb0;

    if (ha * wb < hb * wa) {
        swap(ha, hb);
        swap(wa, wb);
    }

    int64 g = gcd((int64)wa, (int64)wb);
    i128 xMax = c / wa;
    i128 yMax = c / wb;
    i128 yCount = min(yMax + 1, wa / g);
    i128 residueCount = min(xMax + 1, wb / g);
    i128 answer = 0;

    if (yCount <= residueCount) {
        for (i128 y = 0; y < yCount; ++y) {
            i128 x = (c - y * wb) / wa;
            answer = max(answer, x * ha + y * hb);
        }
    } else {
        i128 period = wb / g;
        for (i128 r = 0; r < residueCount; ++r) {
            i128 x = xMax - (xMax - r) % period;
            i128 y = (c - x * wa) / wb;
            answer = max(answer, x * ha + y * hb);
        }
    }

    printInt128(answer);
    return 0;
}

