        if (reducedLimit < limit) {
            type = 0;
            limit = reducedLimit;
        }
    }

    i128 answer = 0;

    if (type == 0) {
        for (int64 red = 0; red <= limit; ++red) {
            int64 blue = (c - red * wr) / wb;
            answer = max(answer, (i128)red * hr + (i128)blue * hb);
        }
    } else {
        for (int64 blue = 0; blue <= limit; ++blue) {
            int64 red = (c - blue * wb) / wr;
