int main() {
    ios::sync_with_stdio(false);
    cin.tie(nullptr);

    int64 c, hr, hb, wr, wb;
    cin >> c >> hr >> hb >> wr >> wb;

    int64 wa, ha, wv, hv;
    if ((i128)hr * wb >= (i128)hb * wr) {
        wa = wr, ha = hr;
        wv = wb, hv = hb;
    } else {
        wa = wb, ha = hb;
        wv = wr, hv = hr;
    }

    int64 g = gcd(wa, wv);
    int64 restrictedWorse = min(c / wv, wa / g - 1);
    int64 fullBetter = c / wa;
    i128 answer = 0;

    if (restrictedWorse <= fullBetter) {
        for (int64 y = 0; y <= restrictedWorse; ++y) {
            int64 x = (c - y * wv) / wa;
            answer = max(answer, (i128)x * ha + (i128)y * hv);
        }
    } else {
        for (int64 x = 0; x <= fullBetter; ++x) {
            int64 y = (c - x * wa) / wv;
            answer = max(answer, (i128)x * ha + (i128)y * hv);
        }
    }

    print128(answer);
    return 0;
}

